macro_rules! BlameRanges {
    () => {
        # [doc = " A type to represent one or more line ranges to blame in a file."] # [doc = ""] # [doc = " It handles the conversion between git's 1-based inclusive ranges and the internal"] # [doc = " 0-based exclusive ranges used by the blame algorithm."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " use gix_blame::BlameRanges;"] # [doc = ""] # [doc = " // Blame lines 20 through 40 (inclusive)"] # [doc = " let range = BlameRanges::from_one_based_inclusive_range(20..=40);"] # [doc = ""] # [doc = " // Blame multiple ranges"] # [doc = " let mut ranges = BlameRanges::from_one_based_inclusive_ranges(vec!["] # [doc = "     1..=4, // Lines 1-4"] # [doc = "    10..=14, // Lines 10-14"] # [doc = " ]"] # [doc = " );"] # [doc = " ```"] # [doc = ""] # [doc = " # Line Number Representation"] # [doc = ""] # [doc = " This type uses 1-based inclusive ranges to mirror `git`'s behaviour:"] # [doc = " - A range of `20..=40` represents 21 lines, spanning from line 20 up to and including line 40"] # [doc = " - This will be converted to `19..40` internally as the algorithm uses 0-based ranges that are exclusive at the end"] # [doc = ""] # [doc = " # Empty Ranges"] # [doc = " You can blame the entire file by calling `BlameRanges::default()`, or by passing an empty vector to `from_one_based_inclusive_ranges`."] # [derive (Debug , Clone , Default)] pub enum BlameRanges { # [doc = " Blame the entire file."] # [default] WholeFile , # [doc = " Blame ranges in 0-based exclusive format."] PartialFile (Vec < Range < u32 > >) , }
    };
}

BlameRanges!()